def countOfSubstrings(word: str, k: int) -> int:
    word = word.strip()  # input is lowercase letters only; guard stray whitespace
    vowels = set('aeiou')

    # Count substrings with all 5 vowels and AT MOST kc consonants.
    def at_most(kc):
        if kc < 0:
            return 0
        res = 0
        left = 0
        last_seen = {}      # vowel -> most recent index inside window
        unique_vowels = 0
        consonants = 0
        for right, ch in enumerate(word):
            if ch in vowels:
                if ch not in last_seen or last_seen[ch] < left:
                    unique_vowels += 1
                last_seen[ch] = right
            else:
                consonants += 1
            while consonants > kc:
                lc = word[left]
                if lc in vowels:
                    if last_seen[lc] == left:
                        unique_vowels -= 1
                else:
                    consonants -= 1
                left += 1
            if unique_vowels == 5:
                # Valid starts: [left, min last-seen of all vowels].
                min_start = min(last_seen[v] for v in vowels)
                res += min_start - left + 1
        return res

    # Exactly k consonants = (<= k) - (<= k-1).
    return at_most(k) - at_most(k - 1)
